/**
 * What can go wrong.
 * (The fields are named `detail`, not `message`: Kotlin exceptions
 * already have a `message`.)
 */
sealed class ResonatorException: kotlin.Exception() {
    
    /**
     * The configuration is not valid.
     */
    class Config(
        
        val `detail`: kotlin.String
        ) : ResonatorException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The node could not start (or do what was asked).
     */
    class Node(
        
        val `detail`: kotlin.String
        ) : ResonatorException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The node has been stopped.
     */
    class Stopped(
        ) : ResonatorException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ResonatorException> {
        override fun lift(error_buf: RustBuffer.ByValue): ResonatorException = FfiConverterTypeResonatorError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeResonatorError : FfiConverterRustBuffer<ResonatorException> {
    override fun read(buf: ByteBuffer): ResonatorException {
        

        return when(buf.getInt()) {
            1 -> ResonatorException.Config(
                FfiConverterString.read(buf),
                )
            2 -> ResonatorException.Node(
                FfiConverterString.read(buf),
                )
            3 -> ResonatorException.Stopped()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ResonatorException): ULong {
        return when(value) {
            is ResonatorException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ResonatorException.Node -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ResonatorException.Stopped -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ResonatorException, buf: ByteBuffer) {
        when(value) {
            is ResonatorException.Config -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ResonatorException.Node -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ResonatorException.Stopped -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




